insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4470-1','APX-C-4470',1,0,4,4,'① (0-4s) Morning in a Japanese 1K apartment. Small kitchen with soft morning sunlight. Canned coffee (same as reference image) on a table with a slight lived-in feel. Woman wakes up groggily and picks up the canned coffee in a natural movement. Camera slowly zooms in (dolly-in), cinematic.','In a small Tokyo apartment, a woman wakes up groggily and picks up a canned coffee from the table as the camera slowly zooms in.','guest','none','canned coffee','hero','Japanese apartment kitchen','medium','eye','push-in','real-time','soft morning sunlight','none','calm') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
