insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3700-1','APX-C-3700',1,NULL,NULL,NULL,'Subject: One board with a 2D anime-style character. The main camera is fixed at the diagonal rear of the board, and the shot is continuous. Embed a small circular wipe frame in the top right to make the character''s face constantly visible from the front. The circular wipe has clear frame edges and continues to show the character''s expressions (surprise, excitement, exhilaration) in high resolution.
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3700-2','APX-C-3700',2,NULL,NULL,NULL,'Starting in a vast blue sky zone of a realistic water park, against a backdrop of tropical greenery (palm trees, tropical scenery), the character starts from the top of a water slide while on the board.','Against a backdrop of palm trees and tropical greenery, the rider starts from the top of a water slide.','guest','none','none','none','tropical water park','wide','low','tracking','real-time','bright tropical daylight','water','playful') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
