insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3700-4','APX-C-3700',4,NULL,NULL,NULL,'Maintain the main frame by following the board so that the slide rails, curves, water splashes, and light reflections can be clearly read from behind. In the top right circular wipe, the character''s face, shoulders, and hair sway in the wind, eyes change from sparkling surprise to joy, hair flutters under the speed, and they have a startled expression the moment the water hits.','The inset view shows the rider''s expression shift from surprised to thrilled as wind and spray hit their face.','guest','sliding','none','none','tropical water park','cu','pov','tracking','real-time','bright tropical daylight','water','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3700-5','APX-C-3700',5,NULL,NULL,NULL,'Eventually, they dash through a high-speed straight section and enter a pool-like landing zone.','They rocket through a fast straight stretch toward the landing pool.','guest','sliding','none','none','tropical water park','wide','low','tracking','real-time','bright tropical daylight','water','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3700-6','APX-C-3700',6,NULL,NULL,NULL,'At the moment of landing, a large explosion of water. While slowing down, the water is enveloped in light, and a feeling of exhilaration fills the entire screen. The wipe also shows the character''s shining eyes and refreshing smile at the moment of landing.','A huge splash erupts on landing, and the rider''s face lights up with a refreshed, joyful smile.','guest','none','none','none','tropical water park landing pool','wide','eye','tracking','slow-mo','sunlit water spray','water','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
