insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-5029-2','APX-C-5029',2,NULL,NULL,NULL,'As the baby crawls, the hospital floor and walls fluidly transform around them without cutting. The environment morphs into a colorful chaotic kindergarten classroom filled with finger paintings, scattered toys, alphabet posters, tiny chairs, crayons, and sunlight. The child now runs energetically through the room laughing loudly, tripping, falling, then immediately getting back up. Other children scream and play wildly in the background. The camera continues smoothly tracking right.','The room morphs into a colorful kindergarten as the child runs, laughs, trips, and pops back up amid playing classmates.',NULL,'none','none','none','kindergarten classroom','medium','eye','tracking','real-time','bright classroom sunlight','none','playful') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
