insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-5029-5','APX-C-5029',5,NULL,NULL,NULL,'The bedroom walls slide away into a busy college campus walkway. The young adult rushes through crowds carrying books and coffee, stressed but alive, checking their phone while hurrying between classes. Fast-moving students cross frame. Bikes pass. Papers fly in the wind.','The room slides away into a busy college campus as the young adult hurries through crowds with books and coffee.',NULL,'none','coffee','incidental','college campus walkway','medium','eye','tracking','real-time','daytime campus light','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
