insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3210-3','APX-C-3210',3,NULL,NULL,NULL,'Clothing AND visual style change extremely fast (near every frame flicker).\n\nCLOTHING:\nEvery frame = new trendy outfit (no repetition, no blending):\n- modern streetwear\n- layered urban outfits\n- edgy fashion looks\n- contemporary performance wear\n\nSTYLE TRANSFORMATION (identity preserved):\nRapidly shift between unique visual styles:\n\n- realistic human rendering\n- anime-style rendering\n- minimal continuous line art\n- watercolor wash illustration\n- inked comic style (bold outlines, graphic shading)\n- soft pastel illustration\n- textured digital painting\n- rough sketch drawing style\n- marker illustration style\n- paper cut-out collage style\n- clay-like sculpted look\n- low-poly geometric 3D\n- neon outline silhouette style\n- glitch-outline graphic style (clean, non-distorting)\n- storybook illustration style\n- hand-painted brush style\n- chalkboard drawing style\n- airbrush gradient illustration\n- silhouette shadow art style\n\nSTYLE BLENDING BURSTS:\n','Her outfit and the whole rendering style shift at high speed, cycling through many trendy looks and art styles while she keeps dancing.',NULL,'none','none','none','dance studio','medium','eye','push-in;orbit','time-remap','dynamic studio light','energy','playful') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3210-4','APX-C-3210',4,NULL,NULL,NULL,'Occasionally combine 2–3 styles in a single frame (e.g., line art + watercolor, comic + low-poly, sketch + digital paint) for brief visual bursts.\n\n','Every so often two or three styles blend in a single flickering burst before returning to the flow.',NULL,'none','none','none','dance studio','medium','eye','handheld','time-remap','dynamic studio light','energy','playful') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
