insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-5182-2','APX-C-5182',2,NULL,NULL,NULL,'As the dancer begins moving slowly, the mercury reacts unnaturally to every gesture. Ripples travel outward like liquid mirrors while reflections distort independently from reality. The dancer’s body moves with elegant fluid choreography, long flowing fabric trailing through metallic waves.','As she moves, the liquid metal ripples outward unnaturally and reflections distort while flowing fabric trails through the metallic waves.',NULL,'none','none','none','liquid silver surface','medium','eye','orbit','slow-mo','soft silver light','water;particles','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-5182-3','APX-C-5182',3,NULL,NULL,NULL,'The camera circles continuously around the performance in one uninterrupted cinematic movement. Every step creates suspended droplets of reflective mercury floating weightlessly in the air. Hands and feet leave temporary silver trails that dissolve slowly into liquid smoke.','The camera circles continuously as every step lifts weightless silver droplets and her hands and feet leave dissolving silver trails.',NULL,'none','none','none','liquid silver surface','medium','eye','orbit','slow-mo','soft silver light','particles','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-5182-4','APX-C-5182',4,NULL,NULL,NULL,'The dancer spins gracefully while the mercury rises around the body like living sculpture. Metallic waves twist upward into giant reflective ribbons and mirrored humanoid shapes that mimic the choreography with slight delay.','She spins as the metal rises around her like living sculpture, twisting into giant ribbons and mirrored figures that echo her movements.',NULL,'none','none','none','liquid silver surface','wide','eye','orbit','slow-mo','soft silver light','particles;energy','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-5182-5','APX-C-5182',5,NULL,NULL,NULL,'Mid-sequence, gravity appears to collapse. The dancer floats briefly above the mercury surface while thousands of liquid silver droplets orbit around the body like a frozen galaxy. Reflections fracture infinitely beneath the surface.','Gravity seems to collapse and she floats above the surface as thousands of silver droplets orbit her like a frozen galaxy.',NULL,'none','none','none','black void of liquid silver','wide','eye','orbit','bullet-time','soft silver light','particles','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-5182-6','APX-C-5182',6,NULL,NULL,NULL,'Soft white light pulses through the liquid environment while the dancer performs increasingly surreal movements impossible under normal physics. The mercury stretches, bends, and folds reality around the choreography.','Soft white light pulses through the space as she performs increasingly surreal movements and the metal bends and folds around her.',NULL,'none','none','none','liquid silver void','medium','eye','orbit','slow-mo','pulsing soft white light','energy;particles','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
