insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3182-1','APX-C-3182',1,NULL,NULL,NULL,'@ Image1 sits opposite me, happily eating from her bowl, enjoying rice and other dishes except the West Lake vinegar fish. She looks bright, playful, relaxed, cute.','Seated across an outdoor table by West Lake, a young woman happily eats rice and several dishes, bright and playful, avoiding only the fish dish so far.','guest','feasting','rice and regional dishes','featured','outdoor lakeside dining table, Hangzhou','medium','pov','handheld','real-time','soft daylight','none','playful') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3182-2','APX-C-3182',2,NULL,NULL,NULL,'From first-person POV, I pick up one bite of the fish with chopsticks and slowly extend it toward her. She notices it immediately, trusts me, leans forward, opens her mouth happily, and makes a cute “aam” sound as she bites the fish. I gently pull the chopsticks and my hand back out of frame.','From across the table, the camera-holder offers her a bite of the lake fish dish on chopsticks; she trusts them and happily takes the bite.','guest','biting','West Lake vinegar fish','hero','outdoor lakeside dining table, Hangzhou','cu','pov','handheld','real-time','soft daylight','none','playful') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3182-3','APX-C-3182',3,NULL,NULL,NULL,'She chews happily for about one second, expecting it to taste good. Then the taste hits. Her expression changes instantly into exaggerated but believable disgust. Her face shifts into a comedic purple-disgust reaction while staying within realistic live-action style. She quickly turns toward the lake and spits it out with repeated “ptui, ptui, ptui” sounds. The motion is fast, fluid, and continuous from chewing to rejection.','She chews happily for a second expecting it to be delicious, then the taste hits and her face flips into exaggerated disgust; she turns to the lake and spits it out repeatedly.','guest','none','West Lake vinegar fish','hero','outdoor lakeside dining table, Hangzhou','cu','pov','handheld','real-time','soft daylight','water','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3182-4','APX-C-3182',4,NULL,NULL,NULL,'The moment she starts spitting, I begin laughing in first-person POV and keep laughing through the whole reaction. My laughter sounds genuine, amused, and uncontrollable, coming from behind the camera. The camera shakes slightly from laughing.','The camera-holder bursts out laughing at her reaction, the shot shaking slightly with genuine, uncontrollable laughter.','guest','none','none','none','outdoor lakeside dining table, Hangzhou','cu','pov','handheld','real-time','soft daylight','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3182-5','APX-C-3182',5,NULL,NULL,NULL,'After spitting, @ Image1 sticks out her tongue in disgust, immediately grabs the water on the table','Still grimacing, she sticks out her tongue and reaches for water on the table to wash the taste away.','guest','none','none','none','outdoor lakeside dining table, Hangzhou','cu','pov','handheld','real-time','soft daylight','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
