insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3375-3','APX-C-3375',3,NULL,NULL,NULL,'Scene 3: A composition from the chest up. A smooth circle shot moving from her profile to a front-on view. She shakes her head while her eyes are closed, and her hair sways accordingly. Zoom up as she opens her eyes wide. An emotion of ''Delicious!''. The background turns into emotional graphics with sparkles. The dialogue line ''Yummy!''. Expression is heart-eyes, with stars in her eyes. Cut transition.','Eyes closed, she savors the bite with a happy shiver, then opens her eyes wide with a delighted ''Yummy!'' as sparkly graphics burst around her heart-eyed reaction.','guest','none','ramen','featured','street food stall','medium','eye','orbit','real-time','stall ambient light','sparks','appetising') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
