insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3476-1','APX-C-3476',1,NULL,NULL,NULL,'Opening: The black lion sits calmly in the styling chair wearing the emerald cape, mane slightly overgrown, fluffy, and uneven. A human groomer’s hand enters frame and slowly lifts the messy mane with a fine comb, brushing upward through the thick fur. The strands separate naturally with soft rustling and tactile movement. Transition.','In the upscale styling lounge a black lion sits calmly in the chair wearing an emerald cape, its overgrown mane lifted and brushed upward with a fine comb.','animal-character','none','none','none','luxury animal grooming studio','cu',NULL,'none',NULL,'warm vanity-bulb glow','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3476-2','APX-C-3476',2,NULL,NULL,NULL,'Moistening Pass: From the side angle, a delicate mist is sprayed across the top and front of the lion’s mane. Tiny droplets catch the light. The thick black fur darkens, clumps slightly, and settles into a sleek damp texture as the lion remains still and dignified. Transition.','From the side, a fine mist is sprayed over the mane; the droplets catch the light and the thick fur settles into a sleek damp texture as the lion stays dignified.','animal-character','none','none','none','grooming studio','cu','eye','none',NULL,'','water','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3476-3','APX-C-3476',3,NULL,NULL,NULL,'Structural Cut: Overhead angle. A comb lifts a section of the damp mane, and sharp professional scissors remove the excess in one clean, deliberate line. The trim feels precise and intentional, with crisp satisfying snips and visible chunks of dark fur falling away. Transition.','From overhead, a comb lifts a section of the damp mane and scissors remove the excess in one clean line, with chunks of dark fur falling away.','animal-character','none','none','none','grooming studio','cu','overhead','none',NULL,'','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
