insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4174-1','APX-C-4174',1,NULL,NULL,NULL,'The scene opens on a busy city sidewalk in full motion, captured in a front-facing steadicam shot tracking backward as he walks calmly toward camera through a natural flow of pedestrians while pigeons cross the bright sky above; without breaking stride, he casually raises his hand and snaps his fingers.','On a busy sidewalk in full motion, a man walks calmly toward the backward-tracking camera through the crowd, then casually raises his hand and snaps his fingers.','guest','none','none','none','busy city sidewalk','medium',NULL,'tracking','real-time','natural daylight, strong shadows','none','calm') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4174-2','APX-C-4174',2,NULL,NULL,NULL,'Instantly, a bright spherical shockwave erupts from his hand, with visible air distortion and refracted light, expanding rapidly across the environment, freezing dust and debris mid-air, locking pedestrians in place mid-motion, and suspending pigeons mid-flight as reflections ripple across surrounding glass buildings before everything falls into complete stillness and silence, with fine particles hanging in the sunlight.','A bright spherical shockwave bursts from his hand and freezes everything mid-motion — dust, pedestrians and pigeons all locked in place as fine particles hang in the light.','guest','none','none','none','frozen city sidewalk','wide',NULL,'none','time-remap','daylight','energy;particles','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4174-3','APX-C-4174',3,NULL,NULL,NULL,'The camera continues gliding backward as he walks through the frozen world, his footsteps the only sound, subtly observing his surroundings before approaching a frozen woman with striking red hair in a flowing green dress, her hair suspended mid-motion as she holds a takeaway coffee.','He strolls through the frozen world, his footsteps the only sound, and approaches a still woman with red hair in a green dress holding a takeaway coffee.','guest','none','coffee','incidental','frozen sidewalk','medium',NULL,'tracking',NULL,'daylight','none','calm') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4174-4','APX-C-4174',4,NULL,NULL,NULL,'He steps in, briefly studies the moment, removes the cup from her hand, takes a síp, then carefully places it back exactly as it was.','He takes the cup from her hand, sips it, then carefully places it back exactly as it was.','guest','biting','coffee','featured','frozen sidewalk','cu',NULL,'none',NULL,'daylight','none','playful') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4174-5','APX-C-4174',5,NULL,NULL,NULL,'He then turns his attention to the camera, raises his hand again, and snaps his fingers, releasing a more powerful shockwave that rapidly spreads outward, reversing the effect as motion instantly resumés - pedestrians continue walking, pigeons scatter into flight, the woman carries on unaware still holding her coffee, and debris drops naturally to the ground as full city sound returns.','He snaps his fingers again, sending out a stronger shockwave that reverses the freeze — pedestrians walk on, pigeons scatter, the woman continues unaware and debris drops as the city comes back to life.','guest','none','none','none','city sidewalk','wide',NULL,'none','time-remap','daylight','energy;particles','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4174-6','APX-C-4174',6,NULL,NULL,NULL,'He pauses for a brief moment, then continues walking forward, gradually blending into the crowd while the camera keeps tracking backward, maintaining distance as he disappears into the flow, ending in a smooth fade out.','He pauses, then walks on and blends back into the flowing crowd as the camera keeps its distance and fades out.','guest','none','none','none','busy city sidewalk','medium',NULL,'tracking','real-time','daylight','none','calm') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-864-1','APX-C-864',1,NULL,NULL,NULL,'A street food vendor in his 40s, broad shoulders, white apron, red bandana headband, stands behind a wok on a night market stall. Just as he prepares a dramatic toss, his phone starts ringing in his pocket. Without hesitation he flips the vegetables and sauce into the air in a perfect arc above the wok under a burst of flame, and at the same moment pulls out his phone and answers it.','A veteran street food vendor tosses a wok of vegetables into a dramatic flaming arc at the exact moment his phone starts ringing, answering it without missing a beat.','chef','flipping','vegetables','featured','night market wok stall','medium','eye','static','real-time','night market warm sodium and neon','fire','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-864-2','APX-C-864',2,NULL,NULL,NULL,'Camera holds tight from the side on the arc above the wok. As the vegetables reach the apex, they suddenly stop — suspended mid-air. Every droplet of sauce and every vegetable piece hangs frozen in a precise sculptural formation above the wok.','The tossed vegetables freeze impossibly in mid-air above the wok, every droplet and piece suspended in a precise floating arrangement.','chef','none','vegetables','hero','night market wok stall','cu','eye','static','bullet-time','night market warm sodium and neon','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-864-3','APX-C-864',3,NULL,NULL,NULL,'Calmly on the phone, the vendor says: “Okay, I’ll do it. I’m in the middle of something right now. I’ll do it after five minutes.” He hangs up.','Still on the phone, the vendor calmly tells the caller he''ll handle it in five minutes and hangs up.','chef','none','none','none','night market wok stall','medium','eye','static','real-time','night market warm sodium and neon','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-864-4','APX-C-864',4,NULL,NULL,NULL,'He checks his watch. He leans forward and examines the suspended arc from different angles, hands behind his back. He pokes one suspended carrot. It stays. He shrugs, reaches up, and rearranges a few pieces into a more aesthetically pleasing formation. Steps back. Assesses. Nods.','He checks his watch, inspects the frozen arc of food from different angles, pokes a suspended carrot, and rearranges a few pieces for a neater look.','chef','garnishing','vegetables','featured','night market wok stall','medium','eye','static','real-time','night market warm sodium and neon','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-864-5','APX-C-864',5,NULL,NULL,NULL,'Finally he casually taps the suspended arc. The vegetables and sauce instantly drop back down into the wok and continue cooking as if nothing happened.','With a casual tap, the suspended food drops back into the wok and keeps cooking as if nothing happened.','chef','flipping','vegetables','featured','night market wok stall','medium','eye','static','real-time','night market warm sodium and neon','fire','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
