insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4402-1','APX-C-4402',1,0,2,2,'Shot 1 (0-2s) Screen: Vintage Chinese teahouse room, red and green painted screens, wooden window frames, blue curtains, tea sets, lanterns, and potted plants. A young woman with double braids in a white dress stands by the tea table, having a greasy, romantic-talk comedy dialogue with a gray tabby cat.','In a cozy vintage teahouse, a young woman in a white dress banters affectionately with her gray tabby cat.',NULL,'none','none','none','vintage Chinese teahouse room','wide','eye','static','real-time','warm vintage','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4402-2','APX-C-4402',2,0,4,4,'0-4 seconds, medium close-up of the woman. She notices the cat has been holding up one paw, narrows her eyes suspiciously, leans forward, points at the cat and says: ''Why have you been sticking your paw out today? Trying to steal my dried fish again?''','The woman notices the cat holding up one paw and teasingly accuses it of trying to steal her dried fish again.',NULL,'none','dried fish','incidental','vintage teahouse, tea table','medium','eye','none','real-time','warm vintage','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4402-3','APX-C-4402',3,4,8,4,'4-8 seconds, cut to a close-up of the cat. The cat sits upright on the tea table with innocent eyes, slowly raises its paw as if making a scissor sign, and its mouth moves seriously: ''Master, I''m not stealing, I''m playing scissors.''','The cat sits primly on the tea table, raises a paw in a mock scissors gesture, and insists with a straight face that it''s only playing a hand game.','animal-character','none','none','none','vintage teahouse, tea table','cu','eye','none','real-time','warm vintage','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4402-4','APX-C-4402',4,8,12,4,'8-12 seconds, cut back to the woman. She pauses, folds her arms in disgust, raises an eyebrow and says: ''Scissors? Who are you playing rock-paper-scissors with?''','Unconvinced, the woman crosses her arms in mock disgust and asks who exactly the cat thinks it''s playing rock-paper-scissors with.',NULL,'none','none','none','vintage teahouse','medium','eye','none','real-time','warm vintage','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4402-5','APX-C-4402',5,12,16,4,'12-16 seconds, cut to a close-up of the cat. The cat suddenly leans in close to the camera, eyes becoming greasy and confident, slowly winks, with the paw still in mid-air: ''I don''t play rock, and I don''t play paper. I only want to snip your heart into my embrace.''','The cat leans in close to the camera with a smug wink, delivering a flirtatious line about only wanting to win her heart.','animal-character','none','none','none','vintage teahouse, tea table','cu','eye','none','real-time','warm vintage','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4402-6','APX-C-4402',6,16,20,4,'16-20 seconds, cut back to a medium close-up of the woman. The woman is first stunned, her face slowly turns a bit red, then she is overwhelmed by the ''greasiness,'' stares with coquettish anger, and points a folding fan at the cat: ''Stupid cat!''','Flustered and blushing, the woman feigns outrage at the cat''s cheesy charm and points a folding fan at it, calling it a silly cat.',NULL,'none','none','none','vintage teahouse','medium','eye','none','real-time','warm vintage','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4402-7','APX-C-4402',7,20,24,4,'20-24 seconds, a slightly wider medium shot. The woman steps back half a step in coquettish anger, then suddenly raises her leg in an exaggerated wuxia-comedy style kick, gently sending the cat flying out of the frame. The cat spins through the air across the lens, still with a proud expression, its tail tracing an exaggerated arc. The woman huffily tidies her dress and turns her head away.','In an exaggerated comedic flourish, the woman kicks the cat off-frame with playful martial-arts flair, then huffily straightens her dress and looks away.',NULL,'none','none','none','vintage teahouse','medium','eye','whip-pan','real-time','warm vintage','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
