insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3559-1','APX-C-3559',1,0,5,5,'[0–5s]: The Plunge An extremely fast, straight vertical drop from a stormy, overcast sky, plummeting right down the length of a towering galleon’s mainmast. The camera falls like a cannonball past tattered canvas sails and thick rigging. Intense camera shake mimics the buffeting of hurricane winds, with heavy raindrops streaking past the lens to emphasize the blistering downward speed.','From a stormy overcast sky the camera drops straight down the length of a tall galleon''s mainmast, falling past tattered sails and rigging with heavy shake and rain streaking past.',NULL,'none','none','none','storm above a galleon''s mast','wide','high','none','real-time','stormy grey overcast','water','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3559-2','APX-C-3559',2,5,10,5,'[5–10s]: The Deck-Level Weave Inches before smashing into the rain-slicked wooden deck, the camera aggressively pulls up, instantly stabilizing into a buttery-smooth, high-speed FPV glide. It threads the needle through a chaotic, brutal boarding skirmish. The camera ducks under a swinging grappling hook, weaves tightly between two sailors clashing cutlasses, and dodges a spray of splintering wood from the ship''s rail.','Just before hitting the wet deck it pulls up into a smooth high-speed glide, threading through a brutal boarding skirmish — ducking a grappling hook, weaving between clashing sailors, and dodging flying splinters.',NULL,'none','none','none','galleon deck mid-battle','medium',NULL,'fpv','real-time','','water;particles','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3559-3','APX-C-3559',3,10,15,5,'[10–15s]: The Slide and Whip-Pan The camera executes a low, water-spraying powerslide beneath a fallen mast, sliding dangerously close to a massive, roaring bronze cannon just as it fires and violently recoils on its thick ropes. Using the explosive flash of the cannon as a transition, the camera executes a vicious, blurred whip-pan 180 degrees to the right—snapping perfectly onto a Royal Navy Commodore in a soaked, gold-braided coat, capturing the exact frame he fires a smoking flintlock pistol directly at the lens.','A low, water-spraying slide passes beneath a fallen mast and a firing cannon, then a fast blurred turn snaps onto a soaked naval commander as he fires a smoking pistol directly at the lens.',NULL,'none','none','none','galleon deck by the cannon','medium',NULL,'whip-pan','real-time','','sparks;water','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-1805-1','APX-C-1805',1,NULL,NULL,NULL,'Comedy action short film style, 15 seconds, one continuous take. Inside a luxurious hotel lobby, an elderly legendary martial arts master in a simple dark jacket and jeans walks slowly toward a revolving door, completely calm and expressionless.','In a luxury hotel lobby, an elderly martial arts master strolls calmly toward the revolving door, utterly unbothered.','guest','none','none','none','luxury hotel lobby, revolving door','wide','eye','tracking','real-time','hotel lobby lighting','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-1805-2','APX-C-1805',2,NULL,NULL,NULL,'More than ten black-clad attackers rush at him from every direction.','A swarm of more than ten attackers rushes at him from every direction.','guest','sprinting','none','none','hotel lobby','wide','eye','tracking','real-time','hotel lobby lighting','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-1805-3','APX-C-1805',3,NULL,NULL,NULL,'He barely uses any force at all, casually brushing them aside, nudging a shoulder, or stepping out of the way at the perfect moment, causing them to crash into each other, tumble into the revolving door, and get spun around and flung out by the moving glass panels.','With barely any effort, he brushes attackers aside and steps out of their way, sending them crashing into each other and tumbling into the spinning glass doors.','guest','none','none','none','hotel lobby, revolving door','medium','eye','tracking','real-time','hotel lobby lighting','shatter','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-1805-4','APX-C-1805',4,NULL,NULL,NULL,'The camera stays close and follows him throughout. The action rhythm is precise and restrained, while his expression never changes.','The camera stays close on him throughout, his precise, restrained movements never breaking his calm expression.','guest','none','none','none','hotel lobby','medium','eye','tracking','real-time','hotel lobby lighting','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
