insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3665-1','APX-C-3665',1,NULL,NULL,NULL,'1. Establishing Village (Slow cinematic pan) Wide aerial shot of a lush green countryside village at sunrise. Rolling hills, rice fields swaying in wind, smoke rising from wooden houses. Soft golden light, peaceful ambient atmosphere, birds flying across the sky. Slow camera push-in.','A slow, sweeping view opens on a lush countryside village at sunrise, with rolling hills, swaying rice fields, and smoke rising from wooden houses in soft golden light.',NULL,'none','none','none','countryside village at sunrise','extreme-wide',NULL,'push-in',NULL,'soft golden sunrise','none','calm') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3665-2','APX-C-3665',2,NULL,NULL,NULL,'2. The Hidden Workshop (Interior reveal) Cut to a cozy wooden inventor’s workshop filled with sketches, mechanical parts, and warm sunlight beams through dusty windows. Camera slowly moves across blueprints of a flying machine. Subtle floating dust particles, intimate mood.','Inside a cosy wooden workshop full of sketches and mechanical parts, warm sunbeams and floating dust drift over blueprints of a flying machine.',NULL,'none','none','none','inventor''s workshop','medium',NULL,'none',NULL,'warm dusty sunbeams','particles','calm') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3665-3','APX-C-3665',3,NULL,NULL,NULL,'3. The Inventor Moment (Character focus) Close-up of a young inventor sketching intensely. Emotional expression, soft lamp lighting on face, hands moving quickly across paper. Camera slowly rotates around character, showing determination and loneliness.','A close view finds a young inventor sketching intently in soft lamplight, the camera slowly circling to show both determination and loneliness.',NULL,'none','none','none','workshop','cu',NULL,'orbit',NULL,'soft lamplight','none','reverent') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3665-4','APX-C-3665',4,NULL,NULL,NULL,'4. Machine Reveal (Hero object shot) The handcrafted flying machine is revealed—wood, brass, fabric wings. Camera low-angle orbit shot, slow dramatic reveal. Light glinting off metal parts. Subtle wind movement makes wings slightly shift.','The handcrafted flying machine of wood, brass, and fabric wings is revealed in a slow low-angle reveal, light glinting off its metal as the wings shift gently.',NULL,'none','none','none','workshop','medium','low','orbit',NULL,'','none','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3665-5','APX-C-3665',5,NULL,NULL,NULL,'5. First Flight Launch (Action sequence) The machine launches from a grassy hill above the village. Fast wind movement, grass bending, villagers running into frame below. Camera follows the machine accelerating upward into sky. Dynamic motion blur.','The machine launches from a grassy hill above the village as grass bends and villagers run into frame below, the camera following it climbing into the sky.',NULL,'none','none','none','grassy hill above the village','wide',NULL,'tracking',NULL,'','none','epic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3665-6','APX-C-3665',6,NULL,NULL,NULL,'6. Mid-air instability (Tension moment) Flying machine tilts in turbulent wind. Camera shakes slightly, dramatic clouds swirling. Close-up of rotating wings struggling. Sound of wind intensifies. Emotional tension builds.
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3665-7','APX-C-3665',7,NULL,NULL,NULL,'8. Above the clouds (Calm transformation) Machine stabilizes above a glowing cloud sea. Peaceful silence replaces tension. Soft golden-orange sky blending into deep blue. Camera drifts slowly around the floating machine.','The machine steadies above a glowing sea of clouds as calm returns, the camera drifting slowly around it under a soft golden-orange and deep blue sky.',NULL,'none','none','none','above a glowing cloud sea','wide',NULL,'orbit',NULL,'golden-orange to deep blue sky','none','calm') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3665-8','APX-C-3665',8,NULL,NULL,NULL,'9. Magical Encounter + Ending (Climactic emotional finish) A glowing ethereal spirit-like light entity appears in the sky near the machine, gently illuminating everything. The inventor looks up in awe. Camera pulls back slowly into a vast sky revealing infinite clouds. Fade out into sunset.','A glowing, ethereal spirit of light appears near the machine and gently lights everything as the inventor looks up in awe and the camera pulls back into a vast sky before fading to a sunset.',NULL,'none','none','none','vast glowing sky','extreme-wide',NULL,'pull-back',NULL,'ethereal glow into sunset','energy;particles','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2090-1','APX-C-2090',1,0,2,2,'Two-shot medium shot. The overall stage setting is a “living room skit,” but surrounded by massive red and gold LED screens. Zhen Huan (left) and Hu Fei (right) sit side-by-side on a modern talk show sofa. Key historical accuracy requirement: Both wear gorgeous, clearly defined Qing Dynasty court robes with standing collars and fine embroidery; hairstyles are authentic “Da La Chi” or “Dian Cui,” adorned with tassels. Hu Fei appears casual, biting a pickled cucumber, with long gold finger guards on her fingers. 2–4 seconds:','Two performers in elaborate historical court robes sit side by side on a modern talk-show sofa in front of festive red and gold screens, one of them casually snacking.',NULL,'none','pickled cucumber','incidental','festive stage set, talk-show sofa','medium','eye','static','real-time','bright festive stage lighting','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2090-2','APX-C-2090',2,2,4,2,'Camera switches to Over-the-Shoulder (OTS) view, focusing on Hu Fei. Hu Fei rolls her eyes exaggeratedly (the classic “eye-roll” expression). She uses her long finger guard to pinch the pickle, pointing and speaking in an arrogant tone (lip-syncing): “This year’s KPI is still fighting these little demons. What does that old emperor know about aesthetics?” 4–6 seconds:','One of them rolls her eyes and delivers a sarcastic line about her workload in an arrogant tone while snacking.',NULL,'biting','pickled cucumber','incidental','festive stage set','medium','eye','static','real-time','bright festive stage lighting','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2090-3','APX-C-2090',3,4,6,2,'Quickly switch to Zhen Huan’s OTS view. Contrast detail: Zhen Huan wears a modern white Bluetooth headset in one ear (a sharp contrast to ancient jewelry) and slides on a thin tablet in her hand. She responds calmly and professionally (lip-syncing): “Sister, don’t be angry, this is called workplace involution. I’m thinking about quitting to sell ‘Truth Water’ (cooling oil).” 6–8 seconds:','The other responds calmly and professionally, a modern earpiece and tablet in hand contrasting with her period costume.',NULL,'none','none','none','festive stage set','medium','eye','static','real-time','bright festive stage lighting','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2090-4','APX-C-2090',4,6,8,2,'Close-up of the coffee table between the two. A modern plastic bubble tea cup, printed with “One Zhang Red” (a famous punishment in the drama), is placed next to a traditional porcelain vase. The camera quickly cuts back to the two. 8–10 seconds:','A close-up shows a modern drink cup beside a traditional vase on the coffee table between them before cutting back to the pair.',NULL,'pouring','bubble tea','incidental','festive stage set, coffee table','cu','eye','static','real-time','bright festive stage lighting','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2090-5','APX-C-2090',5,8,10,2,'Full stage view. Audience laughter effect (presented through lighting changes/spotlights). Hu Fei strikes a final pose: legs crossed, chin raised, rolling her eyes again. Zhen Huan gives a professional, newscaster-like smile to the camera. Golden sequins fall from the air. The festive red atmosphere reaches its peak.','The stage pulls back to a full view as one strikes a final sassy pose and the other gives a polished smile to the camera while golden sequins fall.',NULL,'none','none','none','festive stage set','wide','eye','pull-back','real-time','bright festive stage lighting','particles','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
