insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4178-2','APX-C-4178',2,5,10,5,'She sprays the perfume once into the air, watching the mist sparkle in the light, then gestures toward herself as if describing its scent and feeling. She softly says in English describing it as fresh, elegant, and long-lasting.','She sprays once into the air, watching the mist sparkle in the light, and gestures to herself while describing the scent as fresh, elegant and long-lasting.','guest','none','none','none','studio','medium',NULL,'none','slow-mo','soft golden lighting','particles;lens-flare','calm') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
