insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4386-1','APX-C-4386',1,NULL,NULL,NULL,'Wide cinematic shot of the girl opening the glass café door and walking inside confidently. Warm sunlight passes through large windows, soft ambient café sounds, people blurred in background. Camera follows her from behind then slowly reveals her face from side angle. She wears a classy neutral-toned outfit, carrying a sleek tote bag and laptop. Smooth gimbal movement, luxury lifestyle commercial aesthetic, cozy atmosphere, realistic reflections on glass.','A young woman confidently walks into a sunlit café, camera following her in from behind before revealing her face, dressed elegantly with a tote bag and laptop.','guest','none','none','none','café entrance','wide','eye','tracking','real-time','warm sunlight','none','calm') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4386-2','APX-C-4386',2,NULL,NULL,NULL,'She walks toward a table beside a large window with city view and soft rain/light traffic outside. She places her tote bag down, sits elegantly, opens her slim laptop, and adjusts her coffee cup. Close-up shots of her hands opening the laptop, soft sunlight hitting her face, subtle focus pull from coffee cup to her eyes. Calm productive mood, modern café interior, cinematic framing, warm earthy tones.','She settles at a window table overlooking a rainy city street, setting down her bag, opening her laptop, and adjusting her coffee cup as sunlight catches her face.','guest','none','coffee','incidental','café window table, city view','cu','eye','rack-focus','real-time','warm sunlight','none','calm') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
