insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4386-4','APX-C-4386',4,NULL,NULL,NULL,'Close-up of her enjoying another sip of latte while finishing work. Soft sunlight glows around her hair, peaceful expression, relaxed elegant energy. Camera slowly pulls back revealing the cozy café atmosphere, cake partly finished, laptop open with blurred work screen. Final shot through the café window with cinematic reflections and warm golden-hour lighting. Emotional, inspiring, calm ending frame, premium editorial storytelling, ultra realistic, shallow depth of field, film grain, soft bokeh, luxury coffee advertisement style.','In a final close-up, she takes another peaceful sip of latte as the camera pulls back to reveal the cozy café scene, ending on a warm, golden-hour view through the window.','guest','none','latte, cake','featured','café interior, window','cu','eye','pull-back','real-time','golden-hour','none','calm') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
