insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-894-3','APX-C-894',3,NULL,NULL,NULL,'Camera pulls back as the foam volume doubles every two seconds: doorframe, hallway, staircase, the foam moving with the same even pressure in all directions simultaneously, furniture disappearing beneath the surface. The camera is riding the foam''s leading edge, always just ahead of submersion.','The camera pulls back as the foam keeps doubling in size, spreading evenly through the doorway, down the hallway, and up the staircase, swallowing furniture as it goes, always just a step ahead of the rising tide.',NULL,'none','none','none','house interior, hallway and staircase','wide','pov','pull-back','time-remap','warm interior light','none','comedic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
