insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-1969-4','APX-C-1969',4,NULL,NULL,NULL,'Dialogue (Girl, casual and relaxed tone, speaking Chaozhou dialect): "I didn''t go home for the New Year this year, alone in Shenzhen... Hey, this Malatang is really good! My mother called to ask when I''m getting married, I told her I married the Malatang, hahaha." Sound Effects: Sound of chopsticks hitting the plastic bowl, slurping sound of vermicelli, faint firecracker sounds outside the window, occasional phone notification sounds.','In a relaxed voiceover, she shares that she stayed in the city alone for the holiday and jokes warmly about being "married" to her takeout, over the sound of chopsticks, distant firecrackers, and phone notifications.','guest','none','Malatang','featured','rented apartment living room','medium','high','none','real-time','warm yellow indoor light','none','calm') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
