insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4465-3','APX-C-4465',3,NULL,NULL,NULL,'The colors dissolve again into the lavender-covered hills of Provence, France, where endless purple fields sway like a living ocean beneath the changing light of an entire summer day compressed into seconds. Bees blur through the flowers, horse carts glide silently between rows, and the sky slowly darkens from warm gold to deep indigo.','Endless purple lavender hills sway through a whole summer day compressed into moments as the sky deepens toward dusk.',NULL,'none','none','none','Provence lavender hills','extreme-wide','eye','static','time-remap','shifting daylight from gold to indigo','none','calm') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
