insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4478-1','APX-C-4478',1,0,3,3,'[0:00 – 0:03 | ESTABLISHING SHOT] Extreme low-angle shot looking straight up at the Burj Khalifa piercing through golden morning clouds. Camera slowly tilts down to reveal Maya — a young woman in a sleek wingsuit — standing alone on the observation deck, wind whipping her hair. Dubai glitters endlessly below. She grips the railing. Her knuckles are white.','Looking up a towering skyscraper into golden clouds, the view settles on a young woman alone on the observation deck, gripping the railing as the city glitters far below.','guest','none','none','none','skyscraper observation deck at dawn, Dubai','wide','low','tilt','real-time','golden morning','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4478-2','APX-C-4478',2,3,6,3,'[0:03 – 0:06 | CLOSE-UP CUT] Tight close-up on her eyes — determined, terrified, alive. A crumpled letter escapes her fingers and disappears into the void below. She exhales slowly. She lets go of the railing.','A tight look at her eyes, determined and afraid, as a letter slips from her fingers into the void and she releases her grip.','guest','none','none','none','observation deck edge','ecu','eye','static','real-time','golden morning','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4478-3','APX-C-4478',3,6,10,4,'[0:06 – 0:10 | THE LEAP] Wide cinematic shot — she steps off the edge. Sudden silence for half a second — then the world EXPLODES into motion. She plunges downward, the entire Dubai skyline rushing upward past her. The wingsuit catches air. She extends her arms. Her body transforms from falling to flying. Golden light floods the frame.','She steps off the edge; after a breath of silence the world rushes upward and her fall becomes flight as the wingsuit fills with air.','guest','leaping','none','none','mid-air above the skyline','wide','eye','tracking','real-time','golden light flooding frame','none','epic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4478-4','APX-C-4478',4,10,13,3,'[0:10 – 0:13 | AERIAL FREEDOM] Sweeping drone-style shot from below — Maya soaring horizontally above the city, clouds parting around her, skyscrapers like tiny toys beneath her. Slow motion. Her face — pure, electric joy.','A sweeping view from below as she glides horizontally over the city, clouds parting, skyscrapers tiny beneath her, pure joy on her face.','guest','leaping','none','none','sky above the city','wide','low','drone','slow-mo','bright golden sky','none','epic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-4478-5','APX-C-4478',5,13,15,2,'[0:13 – 0:15 | FADE OUT] She disappears into a blazing golden horizon. Screen fades to black. Voiceover (calm, feminine, powerful): "They told her the sky was the limit. So she jumped from the top of it."','She vanishes into a blazing golden horizon and the frame fades to black.','guest','none','none','none','golden horizon','wide','eye','static','real-time','blazing golden horizon','none','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2160-1','APX-C-2160',1,0,2,2,'Close-up/Wide-angle POV. The tailor rests her hands on the black marble table, head bowed and still. The camera rapidly pushes in, she suddenly raises her head, locking eyes with the camera (a killing gaze). She grabs at the void with her right hand, and a piece of dark purple heavy silk slides across the table like a long snake, which she ''locks'' with one hand.','The tailor rests her hands on a marble table, then suddenly looks up and locks eyes with the camera before catching a length of silk that slides across the table.',NULL,'none','silk fabric','incidental','dim private tailoring studio','cu','eye','push-in','real-time','single cold spotlight','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2160-2','APX-C-2160',2,2,5,3,'Cut transition/Handheld feel. The tailor tosses the silk into the air. Her figure is a blur, holding long silver shears in her right hand, performing a ''blind cut'' the moment the silk falls. This is not an ordinary cut, but one accompanied by the force of a martial arts punch. The scissors cut through the air with a ''hiss,'' and the fabric edge is perfectly straight and neat.','She tosses the silk into the air and cuts it mid-fall with a single, perfectly precise motion of her shears.',NULL,'chopping','silk fabric','incidental','dim private tailoring studio','medium','eye','handheld','real-time','single cold spotlight','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2160-3','APX-C-2160',3,5,7,2,'Moving shot. She slides to the other end of the workbench with a side step. With a single sweep of her hand, several steel needles shake off the pin cushion and hover in mid-air. She pushes them with force, and the needles accurately embed themselves like hidden weapons into the distant mannequin, the needle tails vibrating, emitting a metallic chime.','She steps to the other end of the workbench and flicks several pins through the air, each landing precisely in a distant mannequin.',NULL,'none','none','none','dim private tailoring studio','medium','eye','tracking','real-time','single cold spotlight','sparks','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2160-4','APX-C-2160',4,7,10,3,'Continuous shot. The tailor begins ''thread control.'' She pulls out a gold thread, which, through the winding between her fingers, controls the silk to automatically fold and form in the air, like manipulating a puppet string. Each flick of her finger is accompanied by spark-like static electricity. She bumps the table with her elbow, the presser foot springs up, and she instantly catches and locks it onto the fabric.','She manipulates a gold thread between her fingers, guiding the fabric to fold and form in the air as if by puppetry.',NULL,'none','silk fabric','incidental','dim private tailoring studio','cu','eye','static','real-time','single cold spotlight','sparks','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2160-5','APX-C-2160',5,10,12,2,'Match cut. The tailor performs a rapid pivot in place, and the hem of her outer garment spreads out in a circle. She brings her hands together, sharply pulling the formed suit collar, and the final gold thread draws a perfect arc in the air, automatically stitching the seam. The action transitions from extremely fast (afterimage) to instantaneous extreme slow motion (freeze frame).','She spins in place, pulls the finished collar together, and the last thread stitches the seam in one fluid motion that snaps from a blur into a frozen instant.',NULL,'none','none','none','dim private tailoring studio','medium','eye','static','speed-ramp','single cold spotlight','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-2160-6','APX-C-2160',6,12,15,3,'Stable POV. The dust settles. She lifts the finished gown with one hand and shakes it vigorously, unfolding the gown in front of the camera. The lens focuses on the exquisite embroidery of the collar. She lightly taps a button with her fingernail—the button trembles. She then turns and walks into the shadow, leaving a silhouette, and the screen is completely covered by rising expensive perfume mist, fading out cleanly.','She lifts and unfurls the finished gown for the camera, taps a button on the collar, then turns and walks into the shadows as perfume mist rises and the scene fades.',NULL,'none','none','none','dim private tailoring studio','medium','eye','static','real-time','single cold spotlight','particles','reverent') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-438-1','APX-C-438',1,0,2,2,'Storyboard 0–2 seconds [Late Qing Dynasty Qizhuang] Scene: Enclosed courtyard, low light. Attire: Wide, straight Qizhuang, high collar, wide sleeves, heavy embroidery. Action: Lowering head, slowly raising eyes. First heavy drum beat, sudden rotation. Camera: Medium shot quickly pushing in.','In a dim, enclosed courtyard, a woman in a formal, high-collared antique gown lowers her head, then slowly raises her eyes and spins as the first drum beat lands.',NULL,'none','none','none','enclosed courtyard','medium','eye','push-in','real-time','low courtyard light','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-438-2','APX-C-438',2,2,5,3,'2–5 seconds [1915 Transitional Qipao] Scene: Street, slightly brighter light. Attire: Sleeves narrowed, waistline slightly visible, skirt still long. Action: Landing from rotation, raising head, taking the first step. Rhythm starts to accelerate, rotating again.','On a brighter street, her dress has narrowed at the sleeves and waist as she lands from the spin, lifts her head, and takes her first step, the rhythm quickening into another turn.',NULL,'none','none','none','city street','medium','eye','tracking','real-time','brighter daylight','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-438-3','APX-C-438',3,5,9,4,'5–9 seconds [1920s Shanghai Style] Scene: Shanghai street, tram passing by. Attire: Silk Qipao, clear waistline, length to mid-calf, wavy short hair. Action: Pace significantly accelerates, actively looking at the camera. Camera circling, drum beat intensifies, sharp and clean rotation.','On a 1920s Shanghai street with a tram passing, she now wears a fitted silk dress with short wavy hair, her pace quickening as she looks straight into the camera through a circling shot and a sharp turn.',NULL,'none','none','none','1920s Shanghai street','medium','eye','orbit','real-time','daylight street','none','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-438-4','APX-C-438',4,9,15,6,'9–15 seconds [1930s Golden Age] Scene: Neon night view, strong light outlining the silhouette. Attire: Form-fitting tailoring, high slit, sleeveless, thin high heels, red lips. Action: Rotation completed, stopping, slowly walking towards the camera. Camera shifts from overhead view to eye level. She looks directly at the camera, completely commanding the atmosphere. The final drum beat drops, freeze frame.','Under neon night lights, in a sleek, high-slit gown and heels, she completes her final turn, stops, and walks slowly toward the camera, holding a direct, commanding gaze as the last beat lands and the image freezes.',NULL,'none','none','none','neon-lit night street','medium','eye','crane;tracking','time-remap','neon night light','none','epic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3360-1','APX-C-3360',1,0,4,4,'Wide establishing shot, both dancers step into the open space, lock eyes, strike powerful starting pose. Crowd starts to form and murmur excitedly. 3-8s:','A wide establishing view as both dancers step into the open, lock eyes and strike a powerful starting pose while a crowd begins to gather.',NULL,'none','none','none','Seoul plaza at golden hour','wide','eye','static','real-time','golden-hour light, neon signs','none','playful') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
