insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-5135-2','APX-C-5135',2,NULL,NULL,NULL,'Camera begins with a soft focus foreground of wooden textures, then smoothly shifts focus to her face and outfit details. Subtle lens breathing and natural motion blur enhance realism. Cinematic sunlight rays break through massive fluffy clouds, creating golden highlights across her silhouette and soft rim lighting on her hair and shoulders.','The focus drifts from the wooden foreground to her face and outfit as sunlight breaks through the clouds, casting golden highlights and rim light on her.',NULL,'none','none','none','viewpoint deck','cu','eye','rack-focus','real-time','golden sun rays, soft rim light','lens-flare','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
