insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3426-5','APX-C-3426',5,NULL,NULL,NULL,'The orange glow intensifies and fades rhythmically as the lava shifts, casting animated shadows through the internal structure of the watch, emphasizing depth and engineering precision.','The glow rises and fades in rhythm with the shifting lava, casting moving shadows through the watch''s internal structure and emphasising its engineering.',NULL,'none','none','none','watch interior',NULL,NULL,'none',NULL,'rhythmic orange glow','fire','awe') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-3426-6','APX-C-3426',6,NULL,NULL,NULL,'The strap shows slight thermal tension with minimal, believable movement, while surrounding rocks crack faintly, releasing subtle glowing fragments.','The woven strap shifts subtly under the heat while surrounding rocks crack faintly and release small glowing fragments.',NULL,'none','none','none','volcanic rock',NULL,NULL,'none',NULL,'','sparks;particles','epic') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
