insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-182-1','APX-C-182',1,NULL,NULL,NULL,'Shot 1: Full shot, slow push-in. The scene is extremely still. A young woman wears red and white ethnic attire, adorned with silver jewelry, standing in the mirror-like white salt lake. The sunlight is sacred, with continuous snow-capped mountains in the background. The wind blows her clothes, full of divinity.','A woman in traditional red-and-white dress and silver jewelry stands still on a mirror-flat white salt lake, sacred sunlight and snow-capped mountains behind her, wind stirring her clothes.',NULL,'none','none','none','white salt lake with snow-capped mountains','wide','eye','push-in','real-time','sacred sunlight','none','reverent') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
