insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-959-1','APX-C-959',1,0,3,3,'0-3 seconds [Starting Stance · Swift Exit]: Low-angle back follow, Image 1 side profile gaze, sharp and cold eyes, sudden turn and camera pulls back; Dressed in Song-style cyan clothing, standing with a sword by the waterfall pool Image 3, skimming the water surface with toes, flicking the sword towards the sky, the cyan sword spins into a cyan shadow, flying through the waterfall, clothes fluttering;','A swordsman in flowing cyan robes stands at the edge of a waterfall pool, skims the water with his toes, and flicks his sword skyward before flying through the falls.','agent','leaping','none','none','waterfall pool at base of towering cliff','wide','low','tracking','real-time','misty, natural light through waterfall spray','water','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-959-2','APX-C-959',2,3,6,3,'3-6 seconds [Breaking Shadow · Fanning Back Enemies]: 180° orbit, white-clothed swordsman Image 2 chasing, Image 1 leaning back and sliding to evade, the cyan sword opens and blocks the move; Upward shot as he steps on the cliff face and leaps up, borrowing momentum to ascend, the sword shadow acts as a cyan wing shield;','A rival swordsman in white gives chase; the cyan-robed fighter leans back to evade and blocks with his blade before leaping up the cliff face.','agent','leaping;sliding','none','none','cliff face beside the waterfall','wide','low','orbit','real-time','misty','water','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
insert into shots (shot_id,clip_id,shot_index,tc_in,tc_out,duration_s,verbatim_text,description,subject_role,action,food_item,food_role,setting,camera_framing,camera_angle,camera_movement,motion_speed,lighting,vfx,mood) values ('APX-S-959-3','APX-C-959',3,6,9,3,'6-9 seconds [Chasing Shadow · Fierce Fight]: Fast push-in + spiral ascent, white-clothed swordsman Image 2 lunges, Image 1 holds the sword, condensing energy into a sharp point, the sword shadow forms a cyan screen to block, the energy wave shatters the waterfall, water splashes everywhere; Flying along the cliff face, twisting and turning, the cyan sword stabs, chops, and sweeps, calmly breaking the attack; The white-clothed swordsman pursues closely;','The two fighters trade fierce blows along the cliff face, the cyan-robed swordsman blocking a powerful lunge that sends water splashing everywhere as the pursuit continues.','agent','chopping;leaping','none','none','cliff face beside the shattering waterfall','medium','eye','push-in','real-time','spray and mist from the shattered waterfall','water;energy','intense') on conflict (shot_id) do update set clip_id=excluded.clip_id, shot_index=excluded.shot_index, tc_in=excluded.tc_in, tc_out=excluded.tc_out, duration_s=excluded.duration_s, verbatim_text=excluded.verbatim_text, description=excluded.description, subject_role=excluded.subject_role, action=excluded.action, food_item=excluded.food_item, food_role=excluded.food_role, setting=excluded.setting, camera_framing=excluded.camera_framing, camera_angle=excluded.camera_angle, camera_movement=excluded.camera_movement, motion_speed=excluded.motion_speed, lighting=excluded.lighting, vfx=excluded.vfx, mood=excluded.mood;
